UPDATE "pfms_item_master" im
SET "purchaser" = s.purchaser
FROM "stg_purchaser_import" s
WHERE lower(trim(im."ITEM NAME")) = lower(trim(s.item_name));

COMMIT;

-- ===== Post-migration report (run after COMMIT) =====
SELECT 'item_master rows total' AS metric, count(*)::text AS value FROM "pfms_item_master"
UNION ALL SELECT 'item_master rows with purchaser set', count(*)::text FROM "pfms_item_master" WHERE "purchaser" IS NOT NULL
UNION ALL SELECT 'item_master rows still NULL purchaser', count(*)::text FROM "pfms_item_master" WHERE "purchaser" IS NULL
UNION ALL SELECT 'staging csv rows loaded', count(*)::text FROM "stg_purchaser_import"
UNION ALL SELECT 'dropdown_v2 (new pfms_dropdown) total rows', count(*)::text FROM "pfms_dropdown"
UNION ALL SELECT 'dropdown categories', string_agg(DISTINCT category, ', ') FROM "pfms_dropdown";

